window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-88a8ab3152f9df77"]={"versions": [{"id": "FIG-88a8ab3152f9df77", "releases": ["R3.2.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicher- und PDU-Layout-Diagramm (Bit-/Byte-Mapping) im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm visualisiert ein exemplarisches PDU-Layout, bei dem Datenelemente und E2E-Kontrollfelder nicht den empfohlenen Byte-Grenzen („PDU byte limits“) folgen bzw. unvorteilhaft über Byte-Grenzen hinweg oder asymmetrisch innerhalb des PDU-Puffers angeordnet sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>PDU-Puffer: Horizontales Trägerband, unterteilt durch vertikale graue Trennlinien, die Byte-Grenzen („PDU byte limits“) repräsentieren.\n</li><li>Rote Füllflächen: Unbelegter Speicherbereich bzw. ungenutzte Zwischenräume (Padding/Lücken) innerhalb der PDU.\n</li><li>CRC: Datenfeld für die Prüfsumme (Cyclic Redundancy Check), welches eine Byte-Grenze schneidet (nicht an einer Byte-Grenze ausgerichtet).\n</li><li>Alive: Datenfeld für den Alive-Zähler (Sequenzzähler), positioniert innerhalb eines Bytes ohne Ausrichtung an den Byte-Rändern.\n</li><li>Sig1: Nutznaten-Signal (User Data / Signal), das sich über mehrere Bytes erstreckt und mehrere Byte-Grenzen unbündig überspannt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt einen statischen Speicher- bzw. Serialisierungszustand eines Daten-Frames dar; es zeigt keine zeitliche Sequenz oder Kontrollflussabfolge. Die Datenübertragung bzw. -serialisierung erfolgt typischerweise von links (niedrigere Bit-/Byte-Indizes) nach rechts (höhere Bit-/Byte-Indizes). Beim Serialisieren oder Deserialisieren müssen Bitoperationen (Maskierung, Shift) aufgewendet werden, da die Felder <code>CRC</code>, <code>Alive</code> und <code>Sig1</code> nicht deckungsgleich auf standardisierten Bytegrenzen abschließen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert als Negativbeispiel ein Layout, das den E2E-Design-Empfehlungen widerspricht. Werden E2E-Felder (<code>CRC</code>, <code>Alive Counter</code>) oder Nutzsignale quer über Byte-Grenzen platziert oder nicht an vollen Byte-Adressen ausgerichtet, führt dies zu erhöhtem Rechenaufwand bei der Extraktion/Berechnung und birgt Fehlerrisiken bei Architekturen mit unterschiedlicher Endianness oder restriktiven Alignment-Vorgaben. Für Integratoren und Entwickler gilt die Empfehlung, E2E-Header-Elemente byte-ausgerichtet zu platzieren, um die Recheneffizienz der E2E-Prüfroutinen zu maximieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c159907ae4e31dec", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicher- und PDU-Layout-Diagramm (Bit-/Byte-Mapping) im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm visualisiert ein exemplarisches PDU-Layout, bei dem Datenelemente und E2E-Kontrollfelder nicht den empfohlenen Byte-Grenzen („PDU byte limits“) folgen bzw. unvorteilhaft über Byte-Grenzen hinweg oder asymmetrisch innerhalb des PDU-Puffers angeordnet sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>PDU-Puffer: Horizontales Trägerband, unterteilt durch vertikale graue Trennlinien, die Byte-Grenzen („PDU byte limits“) repräsentieren.\n</li><li>Rote Füllflächen: Unbelegter Speicherbereich bzw. ungenutzte Zwischenräume (Padding/Lücken) innerhalb der PDU.\n</li><li>CRC: Datenfeld für die Prüfsumme (Cyclic Redundancy Check), welches eine Byte-Grenze schneidet (nicht an einer Byte-Grenze ausgerichtet).\n</li><li>Alive: Datenfeld für den Alive-Zähler (Sequenzzähler), positioniert innerhalb eines Bytes ohne Ausrichtung an den Byte-Rändern.\n</li><li>Sig1: Nutznaten-Signal (User Data / Signal), das sich über mehrere Bytes erstreckt und mehrere Byte-Grenzen unbündig überspannt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt einen statischen Speicher- bzw. Serialisierungszustand eines Daten-Frames dar; es zeigt keine zeitliche Sequenz oder Kontrollflussabfolge. Die Datenübertragung bzw. -serialisierung erfolgt typischerweise von links (niedrigere Bit-/Byte-Indizes) nach rechts (höhere Bit-/Byte-Indizes). Beim Serialisieren oder Deserialisieren müssen Bitoperationen (Maskierung, Shift) aufgewendet werden, da die Felder <code>CRC</code>, <code>Alive</code> und <code>Sig1</code> nicht deckungsgleich auf standardisierten Bytegrenzen abschließen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert als Negativbeispiel ein Layout, das den E2E-Design-Empfehlungen widerspricht. Werden E2E-Felder (<code>CRC</code>, <code>Alive Counter</code>) oder Nutzsignale quer über Byte-Grenzen platziert oder nicht an vollen Byte-Adressen ausgerichtet, führt dies zu erhöhtem Rechenaufwand bei der Extraktion/Berechnung und birgt Fehlerrisiken bei Architekturen mit unterschiedlicher Endianness oder restriktiven Alignment-Vorgaben. Für Integratoren und Entwickler gilt die Empfehlung, E2E-Header-Elemente byte-ausgerichtet zu platzieren, um die Recheneffizienz der E2E-Prüfroutinen zu maximieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5cf9a8e66f4f479d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicher- und PDU-Layout-Diagramm (Bit-/Byte-Mapping) im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm visualisiert ein exemplarisches PDU-Layout, bei dem Datenelemente und E2E-Kontrollfelder nicht den empfohlenen Byte-Grenzen („PDU byte limits“) folgen bzw. unvorteilhaft über Byte-Grenzen hinweg oder asymmetrisch innerhalb des PDU-Puffers angeordnet sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>PDU-Puffer: Horizontales Trägerband, unterteilt durch vertikale graue Trennlinien, die Byte-Grenzen („PDU byte limits“) repräsentieren.\n</li><li>Rote Füllflächen: Unbelegter Speicherbereich bzw. ungenutzte Zwischenräume (Padding/Lücken) innerhalb der PDU.\n</li><li>CRC: Datenfeld für die Prüfsumme (Cyclic Redundancy Check), welches eine Byte-Grenze schneidet (nicht an einer Byte-Grenze ausgerichtet).\n</li><li>Alive: Datenfeld für den Alive-Zähler (Sequenzzähler), positioniert innerhalb eines Bytes ohne Ausrichtung an den Byte-Rändern.\n</li><li>Sig1: Nutznaten-Signal (User Data / Signal), das sich über mehrere Bytes erstreckt und mehrere Byte-Grenzen unbündig überspannt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt einen statischen Speicher- bzw. Serialisierungszustand eines Daten-Frames dar; es zeigt keine zeitliche Sequenz oder Kontrollflussabfolge. Die Datenübertragung bzw. -serialisierung erfolgt typischerweise von links (niedrigere Bit-/Byte-Indizes) nach rechts (höhere Bit-/Byte-Indizes). Beim Serialisieren oder Deserialisieren müssen Bitoperationen (Maskierung, Shift) aufgewendet werden, da die Felder <code>CRC</code>, <code>Alive</code> und <code>Sig1</code> nicht deckungsgleich auf standardisierten Bytegrenzen abschließen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert als Negativbeispiel ein Layout, das den E2E-Design-Empfehlungen widerspricht. Werden E2E-Felder (<code>CRC</code>, <code>Alive Counter</code>) oder Nutzsignale quer über Byte-Grenzen platziert oder nicht an vollen Byte-Adressen ausgerichtet, führt dies zu erhöhtem Rechenaufwand bei der Extraktion/Berechnung und birgt Fehlerrisiken bei Architekturen mit unterschiedlicher Endianness oder restriktiven Alignment-Vorgaben. Für Integratoren und Entwickler gilt die Empfehlung, E2E-Header-Elemente byte-ausgerichtet zu platzieren, um die Recheneffizienz der E2E-Prüfroutinen zu maximieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-88a8ab3152f9df77", "to": "FIG-c159907ae4e31dec", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c159907ae4e31dec", "to": "FIG-5cf9a8e66f4f479d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5cf9a8e66f4f479d", "to": "FIG-88a8ab3152f9df77", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
